            this.in = in;
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                ptr = 0;
                len = in.read(buffer);
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public char nextChar() throws IOException {
            int c = readByte();
            while (c <= ' ') {
                if (c == -1) return '\0';
                c = readByte();
            }
            return (char) c;
        }

        public int nextInt() throws IOException {
            int c = readByte();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = readByte();
            }
            int res = 0;
            while (c > ' ') {
                if (c >= '0' && c <= '9') {
                    res = res * 10 + (c - '0');
                }
                c = readByte();
            }
            return res;
        }
    }

    static class FastOutput {
        private final OutputStream out;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;

        public FastOutput(OutputStream out) {
            this.out = out;
        }

        private void writeByte(byte b) throws IOException {
            if (ptr >= buffer.length) {
                flush();
            }
            buffer[ptr++] = b;
        }

        public void writeInt(long val) throws IOException {
            if (val == 0) {
                writeByte((byte) '0');
                return;
            }
            if (val < 0) {
                writeByte((byte) '-');
                val = -val;
            }
            byte[] temp = new byte[20];
            int count = 0;
            while (val > 0) {
                temp[count++] = (byte) ('0' + (val % 10));
                val /= 10;
            }
            while (count > 0) {
                writeByte(temp[--count]);
            }
        }

        public void writeSpace() throws IOException {
            writeByte((byte) ' ');
        }

        public void writeNewline() throws IOException {
            writeByte((byte) '\n');
        }

        public void flush() throws IOException {
            if (ptr > 0) {
                out.write(buffer, 0, ptr);
                ptr = 0;
            }
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        FastOutput writer = new FastOutput(System.out);

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int p = scanner.nextInt();

        int[] row = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            row[i] = i;
        }

        int[] col = new int[m + 1];
        for (int j = 1; j <= m; j++) {
            col[j] = j;
        }

